// Voice guidance: pre-recorded Urdu + English prompts (public/voice/<lang>/<id>.mp3, generated by
// scripts/gen-voice-prompts.mjs from ./prompts.json) and dynamic TTS clips (api.tts URLs).
// One shared <audio> element so prompts never talk over each other.
import { useSyncExternalStore } from 'react'
import type { Lang } from '../types'
import PROMPTS from './prompts.json'

export type VoicePromptId = keyof typeof PROMPTS
export const VOICE_PROMPTS = PROMPTS as Record<VoicePromptId, { ur: string; en: string }>

export function promptUrl(id: VoicePromptId, lang: Lang): string {
  return `/voice/${lang}/${id}.mp3`
}

type State = { playing: string | null }
let state: State = { playing: null }
const listeners = new Set<() => void>()
const set = (s: State) => { state = s; listeners.forEach((l) => l()) }

let audio: HTMLAudioElement | null = null
let token = 0

function el(): HTMLAudioElement {
  if (!audio) {
    audio = new Audio()
    audio.preload = 'auto'
  }
  return audio
}

/** Stop whatever is playing. */
export function stopVoice(): void {
  token++
  if (audio) { audio.pause(); audio.currentTime = 0 }
  set({ playing: null })
}

/** Play a URL; resolves when it ends (or is interrupted / fails). `key` identifies it for UI state. */
export function playUrl(url: string, key = url): Promise<void> {
  const my = ++token
  const a = el()
  a.pause()
  a.src = url
  set({ playing: key })
  return new Promise((resolve) => {
    const done = () => {
      a.removeEventListener('ended', done)
      a.removeEventListener('error', done)
      if (my === token) set({ playing: null })
      resolve()
    }
    a.addEventListener('ended', done)
    a.addEventListener('error', done)
    a.play().catch(done) // autoplay blocked / missing file -> just resolve
  })
}

/** Play a pre-recorded prompt in the given language. */
export function playPrompt(id: VoicePromptId, lang: Lang): Promise<void> {
  return playUrl(promptUrl(id, lang), `${lang}:${id}`)
}

/** Play several prompts back to back (e.g. the same prompt in Urdu then English). Interrupted by any new play. */
export async function playSequence(items: { id: VoicePromptId; lang: Lang }[]): Promise<void> {
  const start = token
  for (const it of items) {
    if (token !== start && token !== start + items.indexOf(it)) return
    await playPrompt(it.id, it.lang)
  }
}

/** Speak to the user with vibration as a non-audio cue too (cheap phones / muted). */
export function buzz(pattern: number | number[] = 30): void {
  try { navigator.vibrate?.(pattern) } catch { /* unsupported */ }
}

/** React hook: which prompt key is playing right now (`<lang>:<id>` or a URL), or null. */
export function useVoicePlaying(): string | null {
  return useSyncExternalStore(
    (cb) => { listeners.add(cb); return () => listeners.delete(cb) },
    () => state.playing,
    () => null,
  )
}

/** True once the user has interacted with the page (browsers block audio autoplay before that). */
export function canAutoplay(): boolean {
  const ua = (navigator as Navigator & { userActivation?: { hasBeenActive: boolean } }).userActivation
  return ua ? ua.hasBeenActive : true
}

const autoplayed = new Set<string>()
/** Auto-play a prompt once per page session (no-op before the first user gesture). */
export function autoplayOnce(id: VoicePromptId, lang: Lang): void {
  const k = `${lang}:${id}`
  if (autoplayed.has(k) || !canAutoplay()) return
  autoplayed.add(k)
  void playPrompt(id, lang)
}
